<script setup lang="ts">
import {safeHref} from '../lib/navigation-links';
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {useI18n} from 'vue-i18n';import {usePreferences} from '../stores/preferences';import {assetUrl} from '../lib/urls';import photos from '../content/team-photos.json';import names from '../content/stats-names.json';
const {locale}=useI18n(),preferences=usePreferences();const zh=computed(()=>locale.value==='zh-CN');const teams=['Mercedes','Ferrari','Red Bull Racing','McLaren','Racing Bulls','Alpine','Haas F1 Team','Audi','Williams','Aston Martin','Cadillac'];
const selected=ref('Ferrari'),index=ref(0),paused=ref(false),hover=ref(false),failed=ref<string[]>([]);
const teamName=(team:string)=>zh.value&&(names as Record<string,string>)[team]||(team);
const slides=computed(()=>photos.filter(p=>preferences.followedTeamIds.includes('openf1:team:'+p.team)&&!failed.value.includes(p.id)).sort((a,b)=>b.captured.localeCompare(a.captured)));
const current=computed(()=>slides.value[index.value%Math.max(1,slides.value.length)]);
const missing=computed(()=>teams.filter(team=>preferences.followedTeamIds.includes('openf1:team:'+team)&&!photos.some(p=>p.team===team)));
watch(slides,()=>{index.value=0;});const move=(n:number)=>{index.value=(index.value+n+slides.value.length)%Math.max(1,slides.value.length);};
let timer:ReturnType<typeof setInterval>|undefined;onMounted(()=>{paused.value=matchMedia('(prefers-reduced-motion: reduce)').matches;timer=setInterval(()=>{if(!paused.value&&!hover.value&&document.visibilityState==='visible'&&slides.value.length>1)move(1);},6000);});onBeforeUnmount(()=>clearInterval(timer));
</script>
<template><section class="team-carousel" aria-roledescription="carousel" :aria-label="zh?'关注主队图片轮播':'Followed team photo carousel'" @mouseenter="hover=true" @mouseleave="hover=false" @focusin="hover=true" @focusout="hover=false"><div class="section-heading"><div><p class="eyebrow">YOUR TEAMS / GALLERY</p><h2>{{zh?'主队影像':'Your teams in focus'}}</h2></div><RouterLink to="/profile">{{zh?'管理关注':'Manage follows'}} ↗</RouterLink></div><div class="carousel-follow"><label>{{zh?'选择主队':'Choose a team'}} <select v-model="selected"><option v-for="team in teams" :key="team" :value="team">{{teamName(team)}}</option></select></label><button class="button" :aria-pressed="preferences.followedTeamIds.includes('openf1:team:'+selected)" @click="preferences.toggleTeam('openf1:team:'+selected)">{{preferences.followedTeamIds.includes('openf1:team:'+selected)?(zh?'取消关注':'Unfollow'):(zh?'关注主队':'Follow team')}}</button></div><figure v-if="current" class="team-slide"><img :key="current.id" :src="assetUrl(current.src)" :alt="current.title" width="1920" height="1280" @error="failed.push(current.id)"/><figcaption><strong>{{teamName(current.team)}}</strong><span>{{zh?'拍摄于':'Captured'}} {{current.captured}} · {{current.author}}</span><span><a :href="safeHref(current.source)" :target="(safeHref(current.source))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{zh?'照片出处':'Photo source'}} ↗</a> · <a :href="safeHref(current.licenseUrl)" :target="(safeHref(current.licenseUrl))?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{current.license}} ↗</a></span></figcaption></figure><p v-else class="empty-inline">{{zh?'关注主队后，这里将轮播相应车队的实拍照片。':'Follow your teams to see their real photographs here.'}}</p><div v-if="slides.length" class="carousel-controls"><button class="button" @click="move(-1)">{{zh?'上一张':'Previous'}}</button><span aria-live="polite">{{index%slides.length+1}} / {{slides.length}}</span><button class="button" @click="paused=!paused">{{paused?(zh?'自动播放':'Play'):(zh?'暂停轮播':'Pause')}}</button><button class="button" @click="move(1)">{{zh?'下一张':'Next'}}</button></div><p class="caption">{{zh?'按已关注车队筛选，优先展示相册中拍摄日期较新的照片；每张图片标明真实日期，并非实时比赛画面。':'Only followed teams are shown, with newer captured photos first. Each photo shows its actual date; these are not live race images.'}}</p><p v-if="missing.length" class="notice">{{missing.map(teamName).join('、')}} · {{zh?'暂无已核验照片':'No verified photos available'}}</p></section></template>
